-- GENERATED by `wfj generate` from data/gossip/gossip-b0.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["b00340ddd5b39ee4"] = { "Devo fare pipì.", "." },
  ["b008158a13a21cdb"] = { "Un'altra ondata, tenete la linea!", "." },
  ["b0093a9c20cfd831"] = { "Non trovo più la mia rana, ⟦Jubjub=Pincopalla⟧. Adora la birra ⟦Dark Iron=Ferroscuro⟧, è l'unica cosa che beve, ma è così difficile da trovare! Ora l'ho finita... e ⟦Jubjub=Pincopalla⟧ dev'essere scappata a cercarne ancora!\n\nVorrei tanto che tornasse...", "." },
  ["b0113d5aa742d34e"] = { "Ciao! Sono Luis! Che ne pensi di me, finora...?", "." },
  ["b014116c5bf28cd2"] = { "Onorato.", "." },
  ["b015b012a70a6922"] = { "%s inizia a lanciare un incantesimo mentre gli prendi il mantello.", "." },
  ["b01776c8f9c84d93"] = { "Non ho tempo di farti da balia! Va' a parlare con il mio assistente, Uthrar!", "." },
  ["b01e4659be39a370"] = { "ORA, STAGHELM! ANDIAMO ORA! Prepara la tua magia!", "." },
  ["b02bcec2e73fb9dc"] = { "Pensavo che sarebbe scorso un po' di sangue se avessi provato a prendere l'acqua dalla pozza. È un peccato che i verrospini non capiscano che tutti gli esseri viventi sono legati tra loro, e che la loro avidità non fa che perpetuare il dolore e la sofferenza del loro popolo. Quanto potrebbero ottenere se mettessero da parte le loro divergenze e i loro clan si unissero.\n\nDi nuovo, un peccato, ma con ogni probabilità una fortuna per le altre razze delle ⟦Barrens=Savane⟧.", "." },
  ["b02d9a57f3c39814"] = { "Purtroppo, anche questo deve essere interrotto... I legami che mi tengono a questo mondo si indeboliscono e mi trascinano via...", "." },
  ["b02e30d6358a7707"] = { "%s percepisce la tua presenza e apre un portale del Nether!", "." },
  ["b040e21a88a1543e"] = { "Oh sì, che meraviglia! Aspettavo un emissario del tuo popolo, e sono molto felice di fare la tua conoscenza.\r\n\nVorrei tanto poterti accogliere nella nostra città natale, Gnomeregan, ma il nostro popolo ha attraversato tempi difficili di recente e la nostra patria, al momento, è perduta.\r\n\nIl re Barbabronzea, però, è sempre amico di noi gnomi, e ci ha gentilmente aperto la sua città in questo momento difficile. \r\n\nSpero che le tue avventure su Azeroth ti trattino bene, e non vedo l'ora di avere altre occasioni per conoscere meglio il tuo popolo. \r\n\nAddio, {name}.", "." },
  ["b042b9dcf0f7d9b8"] = { "Il tuo spietato disprezzo per la potenza sovrana dell'Impero Gurubashi è stato notato. Gli abitanti di ⟦Zul'Gurub=Zul'gurub⟧ sono stati avvisati della tua presenza.", "." },
  ["b04418a10f841dc9"] = { "STOLTO! Pretendi di avere anche solo un decimo del potere che avevi durante la Rivolta? Le nazioni erano unite e furono comunque quasi divorate da un'ombra di Hakkar. Non hai alcuna speranza.", "." },
  ["b04eed8ef39c583d"] = { "Imparare a essere tutt'uno con la Natura agli occhi della Madre Terra è motivo d'orgoglio. Se vuoi imparare le vie del Cacciatore, cerca ⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ all'estremità nord del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "." },
  ["b05795b7e95c15cd"] = { "Ce l'abbiamo fatta, <amico/amica> <mio/mia>. Ricordati di trovare Terenthis e di fargli sapere che siamo salvi. Grazie ancora.", "." },
  ["b066d088f2824964"] = { "Ho perso il mio ⟦Crystal Pylon User's Manual=Manuale d'Uso del Pilastro di Cristallo⟧ e me ne serve un altro.", "." },
  ["b068086eaf3d7b38"] = { "Ben <trovato/trovata>, amico!", "." },
  ["b069f7cd3df3d7d7"] = { "Scopriamo tutta la storia. Ci vorrà un po' di magia...", "." },
  ["b06a2e49d53038e1"] = { "Combattete! Combattete per ⟦Darrowshire=Borgo di Darrow⟧!", "." },
  ["b071fa7d9d89ab32"] = { "Hai passato il tuo tempo a studiare le basi. Ora è il momento di alzare la posta.", "." },
  ["b07322b8b6fe8f09"] = { "Se sopravviverò, farò della distruzione di Arthas l'unico scopo della mia vita...", "." },
  ["b07aac8264affc72"] = { "⟦Stormwind=Roccavento⟧ è il pilastro della razza {race}, sostenuto dalla forza di volontà e dal filo di una solida lama.", "." },
  ["b08195900d7337fd"] = { "Ecco la tua fortuna, {name}. Che ti sia utile.", "." },
  ["b092e1e568336dcd"] = { "Il cinghiale è squisito!", "." },
  ["b09c9139bc485ebc"] = { "Immagino che qualcuno debba pur bendare noi guerrieri dopo la battaglia. Cerca Arnok alla capanna Survival of the Fittest, accanto alla Spirit Lodge nella ⟦Valley of Spirits=Valle degli Spiriti⟧. Guarda in alto, a ovest della ⟦Valley of Strength=Valle della Forza⟧, e troverai un lago. È lì che sta.", "." },
  ["b09e2326883f388d"] = { "Ho sentito che un nobile tra gli elementali dell'acqua, Idraxis, è in guerra con i servitori del fuoco. Speriamo che perda!", "." },
  ["b0a04ac6deab3125"] = { "Dun Baldar è la roccaforte più potente dell'⟦Alliance=Alleanza⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧. Annidata nelle propaggini settentrionali della valle, Dun Baldar è la base di partenza di tutte le avanzate verso sud.\n\nDun Baldar è intatta.", "." },
  ["b0a0bc7e63216e1f"] = { "Quante erbe ha raccolto finora l'⟦Alliance=Alleanza⟧?", "." },
  ["b0aa915254725209"] = { "E buona giornata a te, <coraggioso/coraggiosa> {class}. Lo so che cerchi un buon destriero. Non c'è destriero migliore di un raptor sotto le tue redini, te lo dico io, <fratello/sorella>! Dai un'occhiata a quelli che ho da offrire: allevati dalla razza più feroce che ci sia.", "." },
  ["b0ab6bf1774b15c0"] = { "Ecco... questo dovrebbe aiutare. Ora dimmi cos'è successo, ⟦Grimclaw=Truceartiglio⟧.", "." },
  ["b0bbced5b41d4938"] = { "Il Dun Baldar North Bunker è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["b0bcb61d70a6b07f"] = { "Gli shen'dorei avranno sempre un debito con gli spiriti per il loro aiuto, e i Windshaper hanno giurato di ripagare quel debito e di riportare le cose a com'erano prima. Purtroppo, senza gli spiriti a guidarci, siamo pericolosamente ciechi a ciò che accade intorno a noi in Skywall.\n\nQuelli dell'High Order sono miopi e arroganti, proprio come i loro antenati Alti Nobili. Cercano di dominare e controllare la magia di questo luogo. È proprio la strada che ci ha spinto a fuggire da Kalimdor e a stabilirci qui. Temo che, proprio come per i nostri antenati, la loro sicurezza abbia di gran lunga superato la loro competenza, e il risultato potrebbe essere disastroso.", "." },
  ["b0ca76ef6056be0a"] = { "punto di conquista Win1", "." },
  ["b0ca76f06056be0b"] = { "punto di conquista Win2", "." },
  ["b0cfab88f36b6ab9"] = { "L'⟦Alliance=Alleanza⟧ ha conquistato la segheria!", "." },
  ["b0d15c3e3f6caed6"] = { "<Lo sguardo del ranger davanti a te è fisso sull'enorme pilone d'ancoraggio in lontananza.>", "." },
  ["b0d6e57a1e42e878"] = { "E non so niente di questo tuo fuoco...", "." },
  ["b0dbe70edc82d589"] = { "%s si protegge con la magia.", "." },
  ["b0e2fb5c34c9bf2f"] = { "{name}, <Campione/Campionessa> dello Stormo dei Draghi di Bronzo, ha suonato lo Scarab Gong. Gli antichi cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ si aprono, rivelando gli orrori di una guerra dimenticata...", "." },
  ["b0ecc6e6d43d2a1a"] = { "Ah, {class}, che piacere vederti. Ci serve aiuto per raccogliere rifornimenti in vista dell'imminente guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Mi hanno chiesto di preparare moltissimi kit di pronto soccorso da campo, e il componente principale che mi serve sono le Bende di Lana. Ne ho già un po', $2079w per la precisione, ma devo raccoglierne $2080w.", "." },
  ["b0fcab4ebe7556d3"] = { "Salve, {name}. Se vuoi imparare qualcosa di cucina, vieni a trovarmi quando vuoi.", "." },
  ["b0ffb76048d38b8e"] = { "Mi unisco a voi per celebrare la più venerata delle notti: la notte in cui noi Reietti spezzammo il giogo oppressivo del Flagello!", "." },
})
